import{_ as a,C as n,o as i,c as s,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Persistence Is Not a Wake-Up Mechanism","description":"","frontmatter":{"title":"Persistence Is Not a Wake-Up Mechanism","date":"2026-08-18","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"Why is durable storage insufficient to guarantee that persisted agent work will be noticed and resumed by a live runtime?","summary":"Persistence and reconciliation are different responsibilities. A same-day Codex queue change shows one practical design: detect cross-connection changes coarsely, identify changed queues with durable revisions, reconcile created or resumed objects separately, and give each affected thread its own retry ownership. None of this proves exactly-once execution or distributed exclusivity.","sources":["research/analysis/Q-20260818-02-persistence-reconciliation-separation.md"],"item_id":"Q-20260818-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-18-persistence-reconciliation-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-08-18-persistence-reconciliation.md","filePath":"en/industry/2026-08-18-persistence-reconciliation.md","lastUpdated":1787067160000}'),c={name:"en/industry/2026-08-18-persistence-reconciliation.md"};function l(d,e,h,u,p,m){const t=n("ArticleCover");return i(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-08-18-persistence-reconciliation-cover-v2.png",kicker:"Industry Architecture · Daily Research",title:"Persistence Is Not a Wake-Up Mechanism",summary:"Persistence and reconciliation are different responsibilities. A same-day Codex queue change shows one practical design: detect cross-connection changes coarsely, identify changed queues with durable revisions, reconcile created or resumed objects separately, and give each affected thread its own retry ownership. None of this proves exactly-once execution or distributed exclusivity.",version:"Q-20260818-02",status:"Daily Runtime V5 · 2026-08-18",languageHref:"/zh/industry/2026-08-18-persistence-reconciliation",languageLabel:"中文"}),e[0]||(e[0]=o('<h1 id="persistence-is-not-a-wake-up-mechanism" tabindex="-1">Persistence Is Not a Wake-Up Mechanism <a class="header-anchor" href="#persistence-is-not-a-wake-up-mechanism" aria-label="Permalink to &quot;Persistence Is Not a Wake-Up Mechanism&quot;">​</a></h1><p>A task can be perfectly durable and still never run. The bytes survive, the queue entry is intact, and the system can recover the state after a restart—yet an already-running worker may have no reason to look again after another process changes that state.</p><p>That gap separates <strong>persistence</strong> from <strong>reconciliation</strong>. Persistence answers whether work survives. Reconciliation answers how a live runtime discovers that surviving work has become relevant and attempts progress.</p><p>A merged Codex change on 2026-08-18 provides a concrete SQLite-backed example. The queue watcher uses <code>PRAGMA data_version</code> as a coarse signal that another connection committed a write, durable per-thread revisions to identify which loaded queues changed, explicit reconciliation for created or resumed threads, and separate per-thread retry tasks so one blocked wake does not serialize unrelated queues.</p><p>The implementation does not claim distributed exactly-once execution. Its value is more basic and more reusable: it shows the responsibilities a durable system still needs after storage has done its job.</p><h2 id="durable-state-can-remain-dormant" tabindex="-1">Durable state can remain dormant <a class="header-anchor" href="#durable-state-can-remain-dormant" aria-label="Permalink to &quot;Durable state can remain dormant&quot;">​</a></h2><p>An in-memory wake signal works only while the producer and consumer share the same live process and notification path. Once a queue can be modified through another connection or process, the persistent store becomes a source of truth that may change outside the worker&#39;s immediate view.</p><p>SQLite&#39;s <code>data_version</code> gives the watcher an inexpensive answer to “did another connection change this database?” It does not identify the exact write, actor or affected queue. That is why the implementation adds durable per-thread revisions and a <code>changes_since</code> query. The first signal is coarse; the second narrows the changed set to loaded objects.</p><p>This two-level pattern is useful beyond SQLite:</p><ul><li>a store-level signal says <strong>something may have changed</strong>;</li><li>an object-level identity says <strong>which durable work changed</strong>;</li><li>a reconciliation step decides <strong>whether that work is now actionable</strong>.</li></ul><p>The revision is evidence of change, not evidence of execution. Treating it as a work token would collapse discovery and ownership into one mechanism.</p><h2 id="reconciliation-also-has-a-lifecycle-problem" tabindex="-1">Reconciliation also has a lifecycle problem <a class="header-anchor" href="#reconciliation-also-has-a-lifecycle-problem" aria-label="Permalink to &quot;Reconciliation also has a lifecycle problem&quot;">​</a></h2><p>Database changes are not the only way an object becomes relevant. A thread can be newly loaded or explicitly resumed after the underlying data was already written. If the runtime watches only fresh global store mutations, that thread can miss its chance to be examined.</p><p>The Codex watcher therefore treats created and resumed threads as separate reconciliation inputs. It can scan them from revision zero even when the global database-change signal has not moved in the current observation window. If its created-thread broadcast receiver lags, it can fall back to the manager&#39;s loaded-thread list.</p><p>This is a subtle but important distinction: <strong>external-change detection and local lifecycle discovery are different triggers for the same reconciliation responsibility.</strong> A durable-work design needs to name both.</p><h2 id="retry-ownership-should-be-narrow" tabindex="-1">Retry ownership should be narrow <a class="header-anchor" href="#retry-ownership-should-be-narrow" aria-label="Permalink to &quot;Retry ownership should be narrow&quot;">​</a></h2><p>Discovery alone does not provide liveness if one failed wake can monopolize the recovery loop. The demonstrated design spawns a watcher-dispatch task per changed thread and keeps at most one active watcher task for that thread. If the queue still contains work and the wake attempt cannot resolve it, that thread sleeps for a fixed 10 seconds and tries again.</p><p>The fixed interval is an implementation choice, not a demonstrated optimum. The architectural point is the ownership boundary. A blocked thread owns its own retry delay; it does not hold a single global retry loop in front of unrelated changed queues.</p><p>At scale, independent retries can create another problem: concurrent pressure. Backoff, jitter, fairness, admission and load shedding may still be necessary. Isolation at the wake layer does not prove isolation at every downstream resource.</p><h2 id="reconciliation-is-not-exclusive-execution" tabindex="-1">Reconciliation is not exclusive execution <a class="header-anchor" href="#reconciliation-is-not-exclusive-execution" aria-label="Permalink to &quot;Reconciliation is not exclusive execution&quot;">​</a></h2><p>The most important boundary appears after a successful wake. Durable revisions can tell a runtime that work changed. A watcher can rediscover an eligible thread and ask the existing execution path to resume it. None of those facts prove that a second runtime did not observe the same change and make the same attempt.</p><p>Systems that require stronger guarantees need another layer: a claim or lease, an idempotency identity, transactional fencing, or an equivalent ownership contract. Exactly-once behavior, consensus and global ordering are not consequences of a good reconciliation loop.</p><p>This distinction changes how durability should be designed. Instead of one vague promise—“the queue is persistent”—the system can state several testable contracts:</p><ol><li><strong>Persistence:</strong> work state survives process loss.</li><li><strong>Change identity:</strong> durable mutations can be located at object scope.</li><li><strong>Reconciliation:</strong> a live runtime can rediscover relevant work after external changes and lifecycle transitions.</li><li><strong>Retry ownership:</strong> one failing object cannot indefinitely stall unrelated rediscovery.</li><li><strong>Execution ownership:</strong> if required, a separate claim/idempotency layer prevents unsafe duplicate effects.</li></ol><p>Only the first four are illuminated by the selected change. The fifth remains an explicit engineering question.</p><p>A durable task is therefore not finished when it reaches disk. Durability becomes operationally useful only when the system also specifies who notices it, how resumed objects re-enter the scan, who owns a failed wake, and what separate mechanism prevents duplicate execution where that matters.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/openai/codex/commit/eeb82a156d1b3944dca4234c3043296529ec5837" target="_blank" rel="noreferrer">OpenAI Codex merged commit eeb82a15</a>. The implementation and repository tests are public primary-source evidence; they do not establish independent multi-process reliability or distributed exactly-once behavior.</p>',27))])}const b=a(c,[["render",l]]);export{y as __pageData,b as default};
